source='''def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Horizontal color bands encode samples of a vertical repeating sequence.
    row_values = []
    row_bands = True
    for row in grid:
        colors = {v for v in row if v != 0}
        if len(colors) > 1:
            row_bands = False
            break
        row_values.append(next(iter(colors)) if colors else None)

    if row_bands:
        for period in range(1, h + 1):
            pattern = {}
            valid = True
            for r, color in enumerate(row_values):
                if color is None:
                    continue
                residue = r % period
                if residue in pattern and pattern[residue] != color:
                    valid = False
                    break
                pattern[residue] = color
            if valid:
                # The demonstrations provide at least one clue for each residue.
                # Fill any unconstrained residue with the nearest known residue.
                for r in range(h):
                    residue = r % period
                    if residue not in pattern:
                        nearest = min(pattern, key=lambda q: min((residue-q) % period, (q-residue) % period))
                        pattern[residue] = pattern[nearest]
                return [[pattern[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise the clues lie on diagonal bands: color depends on (column-row) mod p.
    for period in range(1, max(h, w) + 1):
        pattern = {}
        valid = True
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color == 0:
                    continue
                residue = (c - r) % period
                if residue in pattern and pattern[residue] != color:
                    valid = False
                    break
                pattern[residue] = color
            if not valid:
                break
        if valid:
            for residue in range(period):
                if residue not in pattern:
                    nearest = min(pattern, key=lambda q: min((residue-q) % period, (q-residue) % period))
                    pattern[residue] = pattern[nearest]
            return [[pattern[(c-r) % period] for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
